-- Supabase SQL Editor에서 한 번 실행하세요.
create table if not exists public.verses (
  id bigint generated by default as identity primary key,
  text text not null, reference text not null, category text not null, description text not null,
  is_active boolean not null default true, created_at timestamptz not null default now(),
  unique(reference, text)
);
create table if not exists public.favorites (
  id bigint generated by default as identity primary key,
  user_id uuid not null references auth.users(id) on delete cascade,
  verse_id bigint not null references public.verses(id) on delete cascade,
  created_at timestamptz not null default now(), unique(user_id, verse_id)
);
alter table public.verses enable row level security;
alter table public.favorites enable row level security;
drop policy if exists "Anyone can read active verses" on public.verses;
create policy "Anyone can read active verses" on public.verses for select using (is_active = true);
drop policy if exists "Users read own favorites" on public.favorites;
create policy "Users read own favorites" on public.favorites for select to authenticated using (auth.uid() = user_id);
drop policy if exists "Users insert own favorites" on public.favorites;
create policy "Users insert own favorites" on public.favorites for insert to authenticated with check (auth.uid() = user_id);
drop policy if exists "Users delete own favorites" on public.favorites;
create policy "Users delete own favorites" on public.favorites for delete to authenticated using (auth.uid() = user_id);

