insert into public.verses (text, reference, category, description) values ('내게 능력 주시는 자 안에서 내가 모든 것을 할 수 있느니라','빌립보서 4:13','용기','내 능력의 한계만 바라보면 두려움이 커질 수 있습니다. 하나님께서 주시는 힘을 의지하며 오늘 맡겨진 일을 한 걸음씩 감당해 보세요.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('여호와는 나의 목자시니 내게 부족함이 없으리로다','시편 23:1','평안','미래가 불확실하게 느껴질 때 모든 것을 혼자 책임져야 한다고 생각하지 않아도 됩니다. 하나님께서 인도하시는 목자이심을 기억하며 마음을 맡겨 보세요.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('수고하고 무거운 짐 진 자들아 다 내게로 오라 내가 너희를 쉬게 하리라','마태복음 11:28','위로','지치고 마음이 무거울 때조차 혼자 견딜 필요는 없습니다. 자신의 걱정과 부담을 하나님께 솔직하게 내려놓고 쉼을 구해 보세요.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('두려워하지 말라 내가 너와 함께 함이라','이사야 41:10','용기','두려움이 없다는 것이 용기는 아닙니다. 두려운 상황에서도 하나님이 함께하심을 믿으며 앞으로 나아가는 것이 믿음의 용기입니다.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('너는 마음을 다하여 여호와를 신뢰하고 네 명철을 의지하지 말라','잠언 3:5','지혜','내 판단이 항상 완전한 것은 아닙니다. 중요한 선택 앞에서는 자신의 경험뿐 아니라 말씀과 기도를 통해 방향을 점검해 보세요.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('사랑은 오래 참고 사랑은 온유하며','고린도전서 13:4','사랑','사랑은 단순한 감정만이 아니라 상대를 존중하고 기다려 주는 행동으로 나타납니다. 오늘 가까운 사람에게 온유함을 실천해 보세요.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('강하고 담대하라 두려워하지 말며 놀라지 말라','여호수아 1:9','담대함','새로운 책임이나 큰 일을 앞두고 긴장되는 것은 자연스럽습니다. 중요한 것은 두려움 때문에 멈추지 않고 하나님을 의지하며 맡은 길을 계속 걷는 것입니다.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('범사에 감사하라','데살로니가전서 5:18','감사','감사는 모든 상황이 좋다는 뜻이 아닙니다. 어려움 속에서도 여전히 남아 있는 은혜와 가능성을 발견하는 믿음의 태도입니다.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('쉬지 말고 기도하라','데살로니가전서 5:17','기도','기도는 특별한 순간에만 하는 일이 아닙니다. 일하고 이동하고 고민하는 일상 속에서도 짧게 하나님께 마음을 말씀드릴 수 있습니다.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('항상 기뻐하라','데살로니가전서 5:16','기쁨','기쁨은 어려움이 없어서 생기는 감정만을 의미하지 않습니다. 상황보다 하나님께 소망을 두면서 다시 일어설 힘을 발견할 수 있습니다.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('철이 철을 날카롭게 하는 것 같이 사람이 그의 친구의 얼굴을 빛나게 하느니라','잠언 27:17','관계','좋은 관계는 서로를 무조건 편하게만 해주는 관계가 아닙니다. 격려와 조언을 통해 서로 더 좋은 사람으로 성장하도록 돕는 관계도 소중합니다.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('유순한 대답은 분노를 쉬게 하여도','잠언 15:1','관계','상대가 강하게 말할수록 나도 강하게 대응하고 싶어질 수 있습니다. 그러나 차분하고 절제된 한마디가 갈등의 방향을 완전히 바꾸기도 합니다.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('교만은 패망의 선봉이요 거만한 마음은 넘어짐의 앞잡이니라','잠언 16:18','겸손','성공하고 책임이 커질수록 자신이 모든 것을 안다고 생각하기 쉽습니다. 계속 배우고 다른 사람의 의견을 들을 수 있는 겸손을 지켜 보세요.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('무슨 일을 하든지 마음을 다하여 주께 하듯 하고 사람에게 하듯 하지 말라','골로새서 3:23','일과 사명','사람의 평가만 바라보면 인정받지 못할 때 쉽게 지칠 수 있습니다. 내가 맡은 일을 정직하고 성실하게 수행하는 것 자체에 의미를 두어 보세요.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('사람이 마음으로 자기의 길을 계획할지라도 그의 걸음을 인도하시는 이는 여호와시니라','잠언 16:9','진로','계획을 세우는 것은 중요하지만 모든 일이 계획대로 진행되지는 않습니다. 예상하지 못한 변화 속에서도 새로운 길이 열릴 가능성을 기억하세요.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('너의 행사를 여호와께 맡기라 그리하면 네가 경영하는 것이 이루어지리라','잠언 16:3','일과 사명','큰 프로젝트와 새로운 도전을 시작할 때 결과에 대한 부담이 생깁니다. 최선을 다해 준비하되 결과까지 혼자 통제하려 하지 말고 하나님께 맡겨 보세요.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('보라 내가 새 일을 행하리니 이제 나타낼 것이라','이사야 43:19','새로운 시작','과거의 실패가 앞으로의 가능성을 결정하지는 않습니다. 지금까지 없었던 새로운 길이 열릴 수 있다는 소망을 가지고 오늘 할 수 있는 일을 시작해 보세요.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('우리가 선을 행하되 낙심하지 말지니','갈라디아서 6:9','인내','노력의 결과가 바로 나타나지 않을 때 포기하고 싶어질 수 있습니다. 가치 있는 일은 시간이 필요한 경우가 많습니다. 조급함보다 꾸준함을 선택해 보세요.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('너희 염려를 다 주께 맡기라 이는 그가 너희를 돌보심이라','베드로전서 5:7','불안','걱정을 없애려고 억지로 밀어내기보다 무엇이 두려운지 하나님께 솔직하게 말씀드려 보세요. 기도는 걱정을 혼자 짊어지지 않는 연습이기도 합니다.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('내가 산을 향하여 눈을 들리라 나의 도움이 어디서 올까','시편 121:1','도움','해결책이 보이지 않을 때 시선이 문제에만 고정되기 쉽습니다. 잠시 멈추고 내가 의지할 수 있는 하나님과 주변의 도움을 함께 바라보세요.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('여호와를 기다리는 자는 새 힘을 얻으리니','이사야 40:31','회복','계속 달리는 것만이 전진은 아닙니다. 때로는 기다리고 회복하는 시간이 다음 걸음을 위한 중요한 준비가 됩니다.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('마음의 즐거움은 양약이라도','잠언 17:22','기쁨','웃음과 기쁨도 삶에서 중요한 부분입니다. 해야 할 일에만 매달리기보다 감사할 일과 즐거운 순간을 의식적으로 발견해 보세요.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('서로 친절하게 하며 불쌍히 여기며 서로 용서하기를','에베소서 4:32','용서','용서는 잘못을 없었던 일로 만드는 것이 아니라 미움이 자신의 마음을 계속 지배하지 않도록 내려놓는 과정으로 볼 수 있습니다.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('화평하게 하는 자들은 화평으로 심어 의의 열매를 거두느니라','야고보서 3:18','화해','갈등에서 반드시 상대를 이기는 것이 최선은 아닙니다. 진실을 지키면서도 관계를 파괴하지 않는 해결책을 찾는 것이 지혜로운 선택일 수 있습니다.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('구하라 그리하면 너희에게 주실 것이요 찾으라 그리하면 찾아낼 것이요','마태복음 7:7','도전','기도만 하고 기다리는 것과 믿음으로 행동하는 것은 다릅니다. 구하고, 찾고, 두드리라는 말씀처럼 필요한 행동을 실제로 시작해 보세요.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('믿음은 바라는 것들의 실상이요 보이지 않는 것들의 증거니','히브리서 11:1','믿음','아직 결과가 보이지 않는다고 해서 모든 가능성이 사라진 것은 아닙니다. 믿음은 불확실성 속에서도 가치 있는 방향으로 계속 걸어가는 힘이 됩니다.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('소망 중에 즐거워하며 환난 중에 참으며 기도에 항상 힘쓰며','로마서 12:12','소망','힘든 시기에는 현재의 어려움이 영원할 것처럼 느껴질 수 있습니다. 그러나 상황은 변할 수 있습니다. 소망을 붙들고 오늘 하루를 충실하게 살아가 보세요.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('악에게 지지 말고 선으로 악을 이기라','로마서 12:21','선함','상대의 잘못 때문에 나까지 같은 방식으로 행동할 필요는 없습니다. 감정을 절제하고 내가 지키고 싶은 원칙에 따라 행동하는 것이 더 강한 대응일 수 있습니다.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('너희 모든 일을 사랑으로 행하라','고린도전서 16:14','사랑','사랑은 관계에만 적용되는 원칙이 아닙니다. 말하는 방식, 일하는 방식, 사람을 대하는 태도에서도 사랑과 존중을 선택할 수 있습니다.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('지혜가 부족하거든 모든 사람에게 후히 주시는 하나님께 구하라','야고보서 1:5','지혜','모든 답을 알고 있어야 좋은 리더가 되는 것은 아닙니다. 모르는 것을 인정하고 배우며 필요한 지혜를 구하는 태도 자체가 성숙함입니다.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('서로 돌아보아 사랑과 선행을 격려하며','히브리서 10:24','공동체','좋은 공동체는 경쟁만 하는 곳이 아니라 서로의 가능성을 발견하고 격려하는 곳입니다. 오늘 누군가에게 구체적인 격려 한마디를 건네 보세요.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('우리가 알거니와 하나님을 사랑하는 자 곧 그의 뜻대로 부르심을 입은 자들에게는 모든 것이 합력하여 선을 이루느니라','로마서 8:28','소망','현재 이해되지 않는 사건도 시간이 지난 뒤 다른 의미를 갖게 될 수 있습니다. 당장 모든 이유를 알아야 한다는 부담을 내려놓고 지금 할 수 있는 선한 선택에 집중해 보세요.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('나의 은혜가 네게 족하도다 이는 나의 능력이 약한 데서 온전하여짐이라','고린도후서 12:9','약함과 은혜','약점이 있다는 사실이 가치가 없다는 뜻은 아닙니다. 부족함을 인정할 때 오히려 도움을 구하고 배우며 더 단단하게 성장할 수 있습니다.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('눈물을 흘리며 씨를 뿌리는 자는 기쁨으로 거두리로다','시편 126:5','인내','지금의 수고가 당장 보상받지 못하더라도 의미 없는 것은 아닙니다. 보이지 않는 곳에서 쌓이는 노력은 시간이 지나 열매가 될 수 있습니다.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('하나님이 우리에게 주신 것은 두려워하는 마음이 아니요','디모데후서 1:7','담대함','중요한 일을 앞두고 긴장할 수 있습니다. 두려움 자체를 부끄러워하기보다 절제와 사랑과 담대함으로 다음 행동을 선택해 보세요.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('항상 겸손과 온유로 하고 오래 참음으로 사랑 가운데서 서로 용납하고','에베소서 4:2','관계','사람마다 속도와 생각이 다릅니다. 상대를 바꾸려고 서두르기보다 서로의 차이를 존중하면서 필요한 대화를 이어가는 것이 관계를 건강하게 만듭니다.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('사람이 친구를 위하여 자기 목숨을 버리면 이보다 더 큰 사랑이 없나니','요한복음 15:13','사랑','성경이 말하는 사랑에는 희생과 책임이 포함됩니다. 상대에게 무엇을 받을지만 생각하기보다 내가 어떤 선한 사람이 되어 줄 수 있는지도 생각해 보세요.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('너희는 세상의 빛이라','마태복음 5:14','사명','영향력은 높은 지위에서만 생기는 것이 아닙니다. 자신의 자리에서 정직하고 책임 있게 행동하는 작은 선택들이 주변 사람들에게 빛이 될 수 있습니다.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('사람에게 보이려고 그들 앞에서 너희 의를 행하지 않도록 주의하라','마태복음 6:1','겸손','좋은 일을 하면서도 인정받고 싶은 마음이 생길 수 있습니다. 다른 사람의 평가보다 내가 왜 이 일을 하는지 동기를 점검해 보세요.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('내일 일을 위하여 염려하지 말라','마태복음 6:34','불안','아직 일어나지 않은 미래의 문제를 오늘 모두 해결할 수는 없습니다. 미래를 준비하되 오늘 내가 실제로 할 수 있는 일에 집중해 보세요.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
insert into public.verses (text, reference, category, description) values ('항상 소망을 품고','베드로전서 3:15','소망','소망은 현실을 외면하는 낙관이 아니라 어려움 속에서도 삶의 방향과 의미를 잃지 않는 태도입니다.') on conflict (reference, text) do update set category=excluded.category, description=excluded.description, is_active=true;
